package dev.aegis.documents.domain;

/** Where the current display title of a document came from. Stored by name; locale-independent. */
public enum TitleOrigin {
    /** Derived from the uploaded filename; automatic classification may replace it once. */
    FILENAME,
    /** Chosen or confirmed by a member; never replaced automatically. */
    MANUAL,
    /** Generated by automatic classification and not yet changed by a member; later runs may only suggest. */
    AUTOMATIC
}
